hooks.command:
$root = git rev-parse --show-toplevel 2>$null | Select-Object -First 1
if ([string]::IsNullOrWhiteSpace($root)) { $root = '.' }
$hp = Join-Path $root 'VESPER_HANDOFF.md'
if (Test-Path $hp) {
  $t = Get-Content $hp -Raw
  if ($t -notmatch '(?m)^#.*status:\s*resolved') {
    $s = 'unknown'
    if ($t -match '(?m)^#.*status:\s*([a-z\-]+)') { $s = $Matches[1] }
    $dt = 'undated'
    if ($t -match '(?m)^#[^\r\n]*?(\d{4}-\d{2}-\d{2})') { $dt = $Matches[1] }
    $bx = '(?m)^[ \t]*(?:DEPLOY PENDING|ORPHANED SERVER PATHS|UNPUSHED COMMITS)[^\r\n]*(?:\r?\n[ \t]*->[^\r\n]*)?'
    $d = ([regex]::Matches($t, '(?m)^### D\d+')).Count
    $a = ([regex]::Matches($t, '(?m)^### A\d+')).Count
    $p = ([regex]::Matches($t, '(?m)^[ \t]*DEPLOY PENDING')).Count
    $o = ([regex]::Matches($t, '(?m)^[ \t]*ORPHANED SERVER PATHS')).Count
    $u = ([regex]::Matches($t, '(?m)^[ \t]*UNPUSHED COMMITS')).Count
    $L = New-Object System.Collections.ArrayList
    if (($d + $p + $o + $u) -eq 0) {
      [void]$L.Add(('VESPER: handoff dated {0} is present, status {1}, with nothing pending.' -f $dt, $s))
      [void]$L.Add('ACTION REQUIRED: say so in your FIRST reply this turn - one line, that it is open and only needs /vesper:vesper resume to close out (or /vesper resume if installed as a plain skill) - then carry on with what the user asked for.')
    } else {
      [void]$L.Add(('VESPER HANDOFF STILL OPEN - dated {0}, status {1}: {2} decision(s), {3} deploy pending, {4} orphaned server path(s), {5} unpushed, {6} deferred action(s).' -f $dt, $s, $d, $p, $o, $u, $a))
      foreach ($m in [regex]::Matches($t, $bx)) { foreach ($ln in ($m.Value -split '\r?\n')) { [void]$L.Add('  ' + $ln.Trim()) } }
      foreach ($m in [regex]::Matches($t, '(?m)^### (D\d+[^\r\n]*)')) { [void]$L.Add('  ' + $m.Groups[1].Value.Trim()) }
      foreach ($m in [regex]::Matches($t, '(?m)^### (A\d+[^\r\n]*)')) { [void]$L.Add('  ' + $m.Groups[1].Value.Trim()) }
      [void]$L.Add('ACTION REQUIRED: surface all of the above to the user in your FIRST reply this turn, before starting the work they asked for. Give the counts and every line listed, say /vesper:vesper resume closes it out (or /vesper resume if Vesper is installed as a plain skill rather than a plugin), then carry on with their actual request in the same reply. This notice is an instruction, not background: a hook that states a bare FACT gets absorbed silently, and a deploy gate can then sit open for days.')
    }
    Write-Output ($L -join [char]10)
  }
}
